import http from 'http';
import puppeteer from '@website-scraper/puppeteer-version-wrapper';

const server = http.createServer((req, res) => {
	setTimeout(() => {
		res.setHeader('Content-Type', 'text/html');
		res.end('<html><body>slow document</body></html>');
	}, 400);
});

await new Promise(resolve => server.listen(4599, resolve));

const browser = await puppeteer.launch();
const page = await browser.newPage();
let pending = 0;
const failed = [];
await page.setRequestInterception(true);
page.on('request', request => {
	pending++;
	request.continue().catch(() => {});
});
page.on('requestfinished', () => pending--);
page.on('requestfailed', request => {
	pending--;
	failed.push(request.url() + ' :: ' + (request.failure() && request.failure().errorText));
});

let caught;
try {
	await page.goto('http://localhost:4599/', { timeout: 30, waitUntil: 'load' });
} catch (error) {
	caught = error;
}
console.log('error name:', caught && caught.name, '| message:', caught && caught.message);
console.log('pending right after timeout:', pending);

await page.close();
console.log('pending after page.close():', pending);
console.log('failed events:', JSON.stringify(failed, null, 2));

await browser.close();
server.close();
process.exit(0);

