import path from 'path';
import { pathToFileURL } from 'url';
import puppeteer from '@website-scraper/puppeteer-version-wrapper';
import { createRequestInterceptor } from './lib/requestRenderLock.js';

const pageUrl = pathToFileURL(path.resolve('./test/mock/blocked-resources.html')).href;

const browser = await puppeteer.launch();
const page = await browser.newPage();

const interceptor = createRequestInterceptor(['image', 'stylesheet']);
await page.setRequestInterception(true);
page.on('request', interceptor.onRequest);
page.on('requestfinished', interceptor.onRequestFinished);
page.on('requestfailed', interceptor.onRequestFailed);

const seen = [];
page.on('request', request => seen.push({ type: request.resourceType(), url: request.url().split('/').pop() }));

await page.goto(pageUrl, { waitUntil: 'load' });
await new Promise(resolve => setTimeout(resolve, 300));

console.log('seen requests:');
for (const item of seen) {
	console.log(' ', item.type, item.url);
}
console.log('pending after settle:', interceptor.pending);
const scriptRan = await page.evaluate(() => window.blockedScriptLoaded === true);
