import path from 'path';
import { pathToFileURL } from 'url';
import puppeteer from '@website-scraper/puppeteer-version-wrapper';
import { attachInterception } from './lib/requestRenderLock.js';

const fixtureUrl = pathToFileURL(path.resolve('./test/mock/blocked-resources.html')).href;
const browser = await puppeteer.launch();
const page = await browser.newPage();

// mimic the planned test subclass: defer the whole document decision
const attached = await attachInterception(page, { blockResourceTypes: ['image'] });
const { interceptor } = attached;
page.off('request', interceptor.onRequest);
page.on('request', request => {
	if (request.resourceType() === 'document') {
		setTimeout(() => interceptor.onRequest(request), 300);
	} else {
		interceptor.onRequest(request);
	}
});

let caught;
try {
	await page.goto(fixtureUrl, { timeout: 5, waitUntil: 'load' });
} catch (error) {
	caught = error;
}
console.log('error:', caught && caught.name);
console.log('pending right after timeout:', interceptor.pending);
await page.close();
console.log('pending right after close:', interceptor.pending);
await new Promise(resolve => setTimeout(resolve, 400));
console.log('pending after delayed decision fired:', interceptor.pending);
await attached.detach();
await browser.close();
process.exit(0);

