import http from 'http';
import puppeteer from '@website-scraper/puppeteer-version-wrapper';
import { attachInterception } from './lib/requestRenderLock.js';

const server = http.createServer((req, res) => {
	if (req.url === '/') {
		res.writeHead(302, { Location: '/home.html', 'Set-Cookie': 'session=token-2; Path=/' });
		res.end();
		return;
	}
	res.setHeader('Content-Type', 'text/html');
	res.setHeader('Set-Cookie', '__Secure-tracking=1; Path=/');
	res.end(`<html><body><h1>${req.headers.cookie || 'no cookie'}</h1></body></html>`);
});
await new Promise(resolve => server.listen(4598, resolve));

const browser = await puppeteer.launch();
const page = await browser.newPage();
const { interceptor, detach } = await attachInterception(page, {});
try {
	await page.goto('http://localhost:4598/', { waitUntil: 'load' });
} catch (error) {
	console.log('goto error:', error.message);
}
console.log('after goto, pending:', interceptor.pending);
console.log('log:', JSON.stringify(interceptor.log, null, 1));
await page.close();
console.log('after close, pending:', interceptor.pending);
await new Promise(resolve => setTimeout(resolve, 200));
console.log('after tick, pending:', interceptor.pending);
await detach();
await browser.close();
server.close();
process.exit(0);

