import http from 'http';
import puppeteer from '@website-scraper/puppeteer-version-wrapper';

const server = http.createServer((req, res) => {
	console.log('server got', req.url);
	if (req.url === '/') {
		res.writeHead(302, { Location: '/home.html', 'Set-Cookie': 'session=token-2; Path=/' });
		res.end();
		return;
	}
	res.setHeader('Content-Type', 'text/html');
	res.setHeader('Set-Cookie', '__Secure-tracking=1; Path=/');
	res.end(`<html><body><h1>${req.headers.cookie || 'no cookie'}</h1></body></html>`);
});
await new Promise(resolve => server.listen(4597, resolve));

const browser = await puppeteer.launch();
const page = await browser.newPage();
await page.setRequestInterception(true);
const open = new Map();
page.on('request', request => {
	open.set(request.url(), { type: request.resourceType() });
	request.continue().catch(() => {});
});
page.on('requestfinished', request => { open.get(request.url()) && (open.get(request.url()).finished = true); });
page.on('requestfailed', request => { open.get(request.url()) && (open.get(request.url()).failed = (request.failure() || {}).errorText); });

await page.goto('http://localhost:4597/', { waitUntil: 'load' });
console.log('after goto open:', JSON.stringify([...open.entries()], null, 1));
await page.content();
await page.close();
console.log('after close open:', JSON.stringify([...open.entries()], null, 1));
await new Promise(resolve => setTimeout(resolve, 300));
console.log('after tick open:', JSON.stringify([...open.entries()], null, 1));

await browser.close();
server.close();
process.exit(0);

