	state.set(request.url(), 'open');
	request.continue().catch(() => {});
};
const onFinished = request => state.set(request.url(), 'finished');
const onFailed = request => state.set(request.url(), 'failed:' + ((request.failure() || {}).errorText));
page.on('request', onRequest);
page.on('requestfinished', onFinished);
page.on('requestfailed', onFailed);

await page.goto('http://localhost:4596/', { waitUntil: 'load' });
console.log('after goto:', [...state.entries()]);
await page.close();
console.log('after close:', [...state.entries()]);

// second run: disable interception while page still open
const page2 = await browser.newPage();
const state2 = new Map();
await page2.setRequestInterception(true);
page2.on('request', request => { state2.set(request.url(), 'open'); request.continue().catch(() => {}); });
page2.on('requestfinished', request => state2.set(request.url(), 'finished'));
