1	/**
2	 * Keeps plain HTTP requests and puppeteer page renders from overlapping.
3	 *
4	 * A page render may rotate session cookies (via js or Set-Cookie), which
5	 * invalidates the cookie an in-flight plain request was built with. So:
6	 * - requests run concurrently with each other, but never while a render
7	 *   is running or waiting to run;
8	 * - a render runs alone: it waits for in-flight requests to finish and
9	 *   does not overlap with other renders, which could invalidate each other.
10	 */
11	class RequestRenderLock {
12		constructor () {
13			this.requests = 0;
14			this.renders = 0; // running or waiting
15			this.rendering = false;
16			this.waiting = [];
17		}
18	
19		/**
20		 * Resolves when a request may start. Returns a function to call once it finished.
21		 */
22		async startRequest () {
23			while (this.renders > 0) {
24				await this.wait();
25			}
26			this.requests++;
27			return once(() => {
28				this.requests--;
29				this.notify();
30			});
31		}
32	
33		/**
34		 * Resolves when a render may start. Returns a function to call once it finished.
35		 */
36		async startRender () {
37			this.renders++;
38			while (this.requests > 0 || this.rendering) {
39				await this.wait();
40			}
41			this.rendering = true;
42			return once(() => {
43				this.rendering = false;
44				this.renders--;
45				this.notify();
46			});
47		}
48	
49		wait () {
50			return new Promise(resolve => this.waiting.push(resolve));
51		}
52	
53		notify () {
54			const waiting = this.waiting;
55			this.waiting = [];
56			waiting.forEach(resolve => resolve());
57		}
58	}
59	
60	/**
61	 * The single request decision used by every render, including the no-lock
62	 * (exclusiveRendering: false) mode, so a page never gets two competing
63	 * interception handlers.
64	 *
65	 * The pending counter is incremented for every intercepted request and
66	 * released on both requestfinished and requestfailed: aborted requests
67	 * finish as failures rather than successes, so without the failure branch
68	 * networkidle waits would hang until the goto timeout.
69	 */
70	function createRequestInterceptor (blockResourceTypes = []) {
71		const blockedTypes = new Set(blockResourceTypes);
72		const interceptor = {
73			pending: 0,
74			aborted: 0,
75			continued: 0,
76			abandoned: 0,
77			log: []
78		};
79	
80		interceptor.onRequest = request => {
81			const type = request.resourceType();
82			// documents are validated out of blockResourceTypes in the plugin
83			// constructor, keep a guard here so a navigation can never be blanked
84			const blocked = type !== 'document' && blockedTypes.has(type);
85	
86			interceptor.pending++;
87			interceptor.log.push({ type, url: request.url(), blocked });
88	
89			if (blocked) {
90				interceptor.aborted++;
91				request.abort().catch(() => {
92					// the page or target may already be gone (navigation away, page close)
93				});
94			} else {
95				interceptor.continued++;
96				request.continue().catch(() => {
97					// the page or target may already be gone (navigation away, page close)
98				});
99			}
100		};
101	
102		// no clamping: a negative counter means request/finish events are unbalanced,
103		// which assertDrained() below must surface instead of hiding it
104		const release = () => {
105			interceptor.pending--;
106		};
107		interceptor.onRequestFinished = release;
108		interceptor.onRequestFailed = release;
109	
110		interceptor.assertDrained = () => {
111			if (interceptor.pending !== 0) {
112				throw new Error(`request render lock: ${interceptor.pending} intercepted request(s) did not finish`);
113			}
114		};
115	
116		// page.close() terminates every in-flight request, but some of them (e.g.
117		// a continued request whose server never responded, like a hanging favicon)
118		// emit neither requestfinished nor requestfailed. The page teardown is their
119		// terminal event, so reconcile them here instead of leaving the counter stuck.
120		interceptor.drainAbandoned = () => {
121			interceptor.abandoned += interceptor.pending;
122			interceptor.pending = 0;
123			return interceptor.abandoned;
124		};
125	
126		return interceptor;
127	}
128	
129	/**
130	 * Turns interception on for a page and wires the interceptor as the only
131	 * request handler. The returned detach function removes the listeners and
132	 * disables interception again; it is safe to call after the page was closed.
133	 */
134	async function attachInterception (page, options = {}) {
